actions.script:
contentType = null
const content = info.contentEntity
if (!content) return
// the create#<X>Content services (each saves the uploaded contentFile through its save#<X>ContentFile), and the
// enumeration type of the content type field (its relationship title in mr-mantle)
const services = {
    'mantle.ledger.transaction.AcctgTrans': ['mantle.ledger.JournalContentServices.create#Content','acctgTransContentId','AcctgTransContentType'],
    'mantle.product.bom.ProductBom': ['mantle.product.BomServices.create#ProductBomContent', 'productBomContentId', 'ProductBomContentType'],
    'mantle.party.agreement.Agreement': ['mantle.party.AgreementServices.create#AgreementContent', 'agreementContentId', 'AgreementContentType'],
    'mantle.product.maintenance.AssetMaintenance': ['mantle.product.EquipmentServices.create#AssetMaintenanceContent', null, 'AssetMaintContentType'],
    'mantle.party.communication.CommunicationEvent': ['mantle.party.CommunicationServices.create#CommunicationEventContent',
        'communicationEventContentId', 'CommunicationContentType'],
    'mantle.account.invoice.Invoice': ['mantle.account.InvoiceServices.create#InvoiceContent', 'invoiceContentId', 'InvoiceContentType'],
    'mantle.order.OrderHeader': ['mantle.order.OrderServices.create#OrderContent', 'orderContentId', 'OrderContentType'],
    'mantle.party.Party': ['mantle.party.PartyServices.create#PartyContent', 'partyContentId', 'PartyContentType'],
    'mantle.account.payment.Payment': ['mantle.account.PaymentServices.create#PaymentContent', 'paymentContentId', 'PaymentContentType'],
    'mantle.account.method.PaymentMethod': ['mantle.account.PaymentMethodServices.create#PaymentMethodContent', 'paymentMethodContentId',
        'PaymentMethodContentType'],
    'mantle.product.Product': ['mantle.product.ProductServices.create#ProductContent', 'productContentId', 'ProductContentType'],
    'mantle.product.category.ProductCategory': ['mantle.product.ProductServices.create#ProductCategoryContent', 'productCategoryContentId',
        'ProductCategoryContentType'],
    'mantle.request.Request': ['mantle.request.RequestServices.create#RequestContent', 'requestContentId', 'RequestContentType'],
    'mantle.shipment.Shipment': ['mantle.shipment.ShipmentServices.create#ShipmentContent', 'shipmentContentId', 'ShipmentContentType'],
    'mantle.work.effort.WorkEffort': ['mantle.work.WorkEffortServices.create#WorkEffortContent', 'workEffortContentId', 'WorkEffortContentType'],
    'mantle.facility.Facility': [null, 'facilityContentId', 'FacilityContentType'],
    'mantle.product.asset.Asset': ['mantle.product.AssetRecordServices.create#AssetContent', 'assetContentId',
        'AssetContentType'],
    'mantle.order.return.ReturnHeader': ['mantle.order.ReturnServices.create#ReturnContent', 'returnContentId',
        'ReturnContentType'],
    // People's employment content host (impl-people P2, F66): HR's files of an employment, never on the Party
    'mantle.humanres.employment.Employment': ['mantle.humanres.PeopleServices.create#EmploymentContent', 'employmentContentId',
        'EmploymentContentType'],
    // People's application content host (impl-people P16): a recruiter's files of an application (its resume)
    'mantle.humanres.employment.EmploymentApplication': ['mantle.humanres.RecruitingServices.create#ApplicationContent',
        'applicationContentId', 'EmploymentApplicationContentType'],
    // People's qualification content host (impl-people P18, PE-01): a certificate's or document's files, never on the Party
    'mantle.humanres.ability.PartyQualification': ['mantle.humanres.DevelopmentServices.create#QualificationContent',
        'partyQualificationContentId', 'QualificationContentType'],
    // People's review content host (impl-people P20, PE-01): a review's files, never on the Party
    'mantle.humanres.ability.PerformanceReview': ['mantle.humanres.ReviewServices.create#ReviewContent',
        'performanceReviewContentId', 'PerformanceReviewContentType'],
    // People's payslip content host (impl-people P26, PE-01): payroll's files of a payslip, never on the Party
    'mantle.humanres.payroll.Payslip': ['mantle.humanres.PayrollResultServices.create#PayslipContent',
        'payslipContentId', 'PayslipContentType'],
    // IronStone Sales' opportunity content host (impl-sales P4, F69): a lead's or opportunity's files
    'mantle.sales.opportunity.SalesOpportunity': ['mantle.sales.OpportunityServices.create#OpportunityContent',
        'salesOpportunityContentId', 'SalesOpportunityContentType']}
const found = services[info.recordEntityName] || [null, null, null]
const pkFields = Object.keys(ec.entity.makeValue(content.entityName).getPrimaryKeys())
contentType = {entityName: content.entityName, keyField: content.keyField, typeField: content.typeField, dateField: content.dateField,
    pkFields: pkFields, createService: found[0], idField: found[1], enumTypeId: found[2], catalogCanChange: true}
// A visible request is not permission to read the team's internal or unclassified attachments.
contentType.clientRequest = info.recordEntityName === 'mantle.request.Request' && ec.user.hasPermission('PROJECT_CLIENT')
if (contentType.clientRequest) {
    // Mantle's one rule for the request files a customer may see (CaseRelations uses it too)
    contentType.clientContentTypeIds = Array.from(ec.resource
        .script('component://mr-mantle/service/mantle/request/RequestContent.js').customerContentTypeIds)
    contentType.catalogCanChange = false
}
// A journal entry's, invoice's or payment's files: Mantle says who may change them, whether a payment's are kept
// as issued and who reads its checks (catalogCanChange is this service's may-change flag for every kind of record).
if (['mantle.ledger.transaction.AcctgTrans', 'mantle.account.invoice.Invoice', 'mantle.account.payment.Payment']
        .includes(info.recordEntityName)) {
    const finance = ec.service.sync().name('mantle.ledger.AccountingServices.get#RecordContentPolicy')
        .parameters({recordEntityName: info.recordEntityName, recordId: info.recordId}).call()
    // a payment the user may not read has no files to show (Mantle's reason, not its wording)
    if (finance?.reasonCode === 'RECORD_UNAVAILABLE') throw new Error('PAYMENT_UNAVAILABLE: Payment is not available')
    if (!finance?.canChange) {
        ec.logger.info(info.recordEntityName + ' ' + info.recordId + ' files are read only: ' + finance?.reasonCode)
        contentType.catalogCanChange = false
    }
    contentType.paymentContentLocked = !!finance?.contentLocked
    contentType.paymentCanReadCheck = !!finance?.canReadCheck
}
// Catalog content is master data. The same capability holds under Commons, Products and internal callbacks;
// inherited entity permission or having uploaded the file earlier never substitutes for it.
if (['mantle.product.Product', 'mantle.product.category.ProductCategory'].includes(info.recordEntityName)) {
    const access = info.recordId ? ec.service.sync().name('ironstone.products.CatalogServices.get#CatalogRecord')
        .parameters({recordEntityName: info.recordEntityName, recordId: info.recordId, need: 'catalogEdit', checkOnly: true})
        .disableAuthz().call() : null
    contentType.catalogCanChange = !!access?.record
}
if (info.recordEntityName === 'mantle.product.bom.ProductBom') {
    contentType.catalogCanChange = !!ec.service.sync().name('mantle.product.BomServices.get#BomAccess')
        .parameters({productBomId:info.recordId,need:'edit'}).disableAuthz().call()?.recordVisible
}
if (info.recordEntityName === 'mantle.work.effort.WorkEffort') {
    const row = ec.entity.find('mantle.work.effort.WorkEffort').condition('workEffortId',info.recordId).one()
    if (row && ['WepRouting','WepRoutingTask'].includes(row.purposeEnumId)) contentType.catalogCanChange = !!ec.service.sync()
        .name('mantle.work.RoutingServices.get#RoutingAccess').parameters({workEffortId:info.recordId,need:'edit'}).disableAuthz().call()?.recordVisible
    // managed maintenance work (impl-maintenance P7, F69): Mantle's evidence policy says whether its files change (not
    // on closed or cancelled work) and which a check names as evidence, which are never removed or replaced
    if (row) {
        const evidence = ec.service.sync().name('mantle.work.ProcessServices.get#EvidencePolicy')
            .parameters({workEffortId: info.recordId}).disableAuthz().call()
        if (evidence?.managed) {
            if (!evidence.canChange) contentType.catalogCanChange = false
            contentType.protectedContentIds = Array.from(evidence.protectedContentIds || [])
        }
    }
}
// an employment's files: an HR editor of its employer changes them (Mantle's check#EmploymentAccess, People's scope)
if (info.recordEntityName === 'mantle.humanres.employment.Employment') {
    const access = ec.service.sync().name('mantle.humanres.PeopleServices.check#EmploymentAccess')
        .parameters({partyRelationshipId:info.recordId}).disableAuthz().call()
    contentType.catalogCanChange = !!access?.canEdit
}
// P16: an application's files: a recruiter of its employer adds them, its interviewers read them
// (mantle.humanres.RecruitingServices.check#ApplicationAccess)
if (info.recordEntityName === 'mantle.humanres.employment.EmploymentApplication') {
    const access = ec.service.sync().name('mantle.humanres.RecruitingServices.check#ApplicationAccess')
        .parameters({employmentApplicationId:info.recordId}).disableAuthz().call()
    contentType.catalogCanChange = !!access?.canEdit
}
// P18: a qualification's files: the person while it waits or was rejected, and an HR editor of an employer of theirs, change
// them (Mantle's check#QualificationAccess)
if (info.recordEntityName === 'mantle.humanres.ability.PartyQualification') {
    const access = ec.service.sync().name('mantle.humanres.DevelopmentServices.check#QualificationAccess')
        .parameters({partyQualificationId:info.recordId}).disableAuthz().call()
    contentType.catalogCanChange = !!access?.canEdit
}
// P20: a review's files: its reviewer and development editors of its employer add them (Mantle's check#ReviewAccess)
if (info.recordEntityName === 'mantle.humanres.ability.PerformanceReview') {
    const access = ec.service.sync().name('mantle.humanres.ReviewServices.check#ReviewAccess')
        .parameters({performanceReviewId:info.recordId}).disableAuthz().call()
    contentType.catalogCanChange = !!access?.canEdit
}
// P26: a payslip's files: payroll editors of its employer add them (Mantle's check#PayslipAccess)
if (info.recordEntityName === 'mantle.humanres.payroll.Payslip') {
    const access = ec.service.sync().name('mantle.humanres.PayrollResultServices.check#PayslipAccess')
        .parameters({payslipId:info.recordId}).disableAuthz().call()
    contentType.catalogCanChange = !!access?.canEdit
}
// P21: a confidential case's files: its people add them while it is open, nobody else (Mantle's check#PeopleCaseAccess)
if (info.recordEntityName === 'mantle.request.Request' && info.recordId
        && ec.resource.script('component://mr-mantle/service/mantle/request/PeopleCases.js').isCase(info.recordId)) {
    const access = ec.service.sync().name('mantle.request.RequestServices.check#PeopleCaseAccess')
        .parameters({requestId:info.recordId}).disableAuthz().call()
    contentType.catalogCanChange = !!access?.canEdit
}
// Sales P4: a lead's or opportunity's files: its editors add them (Mantle's check#OpportunityAccess, Sales' scope)
if (info.recordEntityName === 'mantle.sales.opportunity.SalesOpportunity') {
    const access = ec.service.sync().name('mantle.sales.OpportunityServices.check#OpportunityAccess')
        .parameters({salesOpportunityId:info.recordId}).disableAuthz().call()
    contentType.catalogCanChange = !!access?.canEdit
}
if (info.recordEntityName === 'mantle.party.Party') {
    const access = ec.service.sync().name('ironstone.commons.ContactServices.check#ContactAccess')
        .parameters({partyId:info.recordId}).disableAuthz().call()
    contentType.catalogCanChange = !!access?.canEdit
}

visible = true
extraList = []
recordsDriveId = null
recordFolderPath = null
filesUrl = null
fileList = []
fileCount = 0
typeOptions = []
defaultTypeId = null
const content = typeOut.contentType
hasContent = !!content
canUpload = hasContent && content.catalogCanChange !== false && ec.artifactExecution.isPermitted(content.entityName, 'AT_ENTITY', 'create')
if (!content) return
const entityName = recordOut.info.recordEntityName
const mayUpdate = content.catalogCanChange !== false && ec.artifactExecution.isPermitted(entityName, 'AT_ENTITY', 'update')
const L = (text) => ec.l10n.localize(text)
const toMillis = (value) => {
    if (value == null || value === '') return null
    if (typeof value === 'number') return value
    if (value instanceof Date) return value.getTime()
    const text = String(value)
    if (/^-?\d+$/.test(text)) return Number(text)
    const parsed = Date.parse(text)
    return Number.isNaN(parsed) ? null : parsed
}
const nowMillis = toMillis(ec.user.nowTimestamp)
const fmt = (millis, pattern) => ec.l10n.format(new Date(Number(millis)), pattern)
const today = fmt(nowMillis, 'yyyy-MM-dd')
const yesterday = fmt(nowMillis - 86400000, 'yyyy-MM-dd')
const whenText = (millis) => {
    if (millis == null) return ''
    const day = fmt(millis, 'yyyy-MM-dd')
    if (day === today) return L('Today') + ' ' + fmt(millis, 'HH:mm')
    if (day === yesterday) return L('Yesterday') + ' ' + fmt(millis, 'HH:mm')
    if (fmt(millis, 'yyyy') === fmt(nowMillis, 'yyyy')) return fmt(millis, 'MMM d')
    return fmt(millis, 'yyyy-MM-dd')
}
const baseName = (location) => {
    const last = location.substring(location.lastIndexOf('/') + 1)
    try { return decodeURIComponent(last) } catch (err) { return last }
}
const sizeText = (size) => {
    if (size == null || size < 0) return ''
    if (size < 1024) return size + ' B'
    if (size < 1024 * 1024) return Math.round(size / 102.4) / 10 + ' KB'
    return Math.round(size / 104857.6) / 10 + ' MB'
}

// the type options: the content type enumeration of the record type
let enumQuery = content.enumTypeId ? ec.entity.find('moqui.basic.Enumeration').condition('enumTypeId', content.enumTypeId) : null
if (enumQuery && content.clientRequest) enumQuery = enumQuery.condition('enumId', 'in', content.clientContentTypeIds)
const enums = enumQuery ? Array.from(enumQuery.orderBy('sequenceNum,description').useCache(true).list()) : []
const typeLabels = {}
for (const item of enums) {
    typeLabels[item.enumId] = item.description || item.enumId
    if (!content.clientRequest) typeOptions.push({value: item.enumId, label: item.description || item.enumId})
}
// an internal or general type first when the enumeration has one
const preferred = enums.find((item) => /Internal$/.test(item.enumId)) || enums.find((item) => /(Other|General|Attachment|SupportingMedia)$/.test(item.enumId))
defaultTypeId = !content.clientRequest && preferred ? preferred.enumId : null

// a payment's check images only for treasury (content.paymentCanReadCheck, from get#RecordContentPolicy)
const isPayment = entityName === 'mantle.account.payment.Payment'
const fileQuery = () => {
    let query = ec.entity.find(content.entityName).condition(content.keyField, recordId)
    if (content.clientRequest) query = query.condition(content.typeField, 'in', content.clientContentTypeIds)
    if (isPayment && !content.paymentCanReadCheck) {
        const cf = ec.entity.conditionFactory
        query = query.condition(cf.makeCondition([cf.makeCondition('contentTypeEnumId', 'is-null', null),
            cf.makeCondition('contentTypeEnumId', 'not-equals', 'PctCheckImage')], 'or'))
    }
    return query
}
const maximum = Math.max(1, Math.min(200, Number(limit || 200)))
fileCount = fileQuery().count()
const rows = Array.from(fileQuery().orderBy('-' + content.dateField).limit(maximum).list())
const names = {}
const nameOf = (userId) => {
    if (!userId) return null
    if (names[userId] === undefined) {
        const account = ec.entity.find('moqui.security.UserAccount').condition('userId', userId).useCache(true).disableAuthz().one()
        names[userId] = account ? (account.userFullName || account.username) : userId
    }
    return names[userId]
}
for (const value of rows.slice(0, limit || 200)) {
    const row = value.getMap()
    // a production instruction is published once and only ended (Mantle store#OperationInstruction)
    const immutable = row.isImmutable === 'Y' || (isPayment && !!content.paymentContentLocked) ||
            (entityName === 'mantle.work.effort.WorkEffort' && row.contentTypeEnumId === 'WectInstruction') ||
            (content.protectedContentIds || []).includes(String(row.workEffortContentId))
    const location = row.contentLocation ? String(row.contentLocation) : ''
    const fileName = location ? baseName(location) : null
    const key = {}
    for (const field of content.pkFields) {
        const fieldValue = row[field]
        key[field] = /Date$/.test(field) ? toMillis(fieldValue) : (fieldValue == null ? null : String(fieldValue))
    }
    // the size and media type from the resource; a file that is gone is still listed, without a size
    let size = null
    let mimeType = null
    if (location) {
        try {
            const ref = ec.resource.getLocationReference(location)
            if (ref && ref.getExists()) {
                size = ref.getSize()
                mimeType = ref.getContentType()
                // a database resource has no size yet (ResourceRef.size); a text file's is its UTF-8 length
                if (size == null && ref.isText()) {
                    const text = ref.getText()
                    if (text != null) {
                        size = 0
                        for (const ch of text) { const code = ch.codePointAt(0); size += code < 0x80 ? 1 : code < 0x800 ? 2 : code < 0x10000 ? 3 : 4 }
                    }
                }
            }
        } catch (err) {
            ec.logger.warn(`Record files of ${entityName} ${recordId}: the file at ${location} could not be read: ${err}`)
        }
    }
    const lower = (fileName || '').toLowerCase()
    const isImage = /\.(png|jpe?g|gif|webp)$/.test(lower)
    const isPdf = /\.pdf$/.test(lower)
    const typeId = row[content.typeField] ?? null
    const dateMillis = toMillis(row[content.dateField])
    fileList.push({contentKey: JSON.stringify(key), fileName: fileName || L('(no file)'), hasFile: !!location,
        contentTypeEnumId: typeId, typeLabel: typeId ? (typeLabels[typeId] || typeId) : null, description: row.description ?? null,
        userId: row.userId ?? null, byName: nameOf(row.userId), dateMillis: dateMillis, dateText: whenText(dateMillis),
        dateFull: dateMillis == null ? '' : fmt(dateMillis, 'yyyy-MM-dd HH:mm'), size: size, sizeText: sizeText(size), mimeType: mimeType,
        isImage: isImage, isPdf: isPdf, icon: isImage ? 'sym_o_image' : isPdf ? 'sym_o_picture_as_pdf'
            : /\.(txt|md|csv|html?|xml|json)$/.test(lower) ? 'sym_o_description' : 'sym_o_draft',
        isImmutable: immutable,
        canRemove: !immutable && content.catalogCanChange !== false && ((!!row.userId && row.userId === ec.user.userId) || mayUpdate), location: location || null})
}

// the record's folder in the records drive (Files, M8): each file's path there for its versions, and the folder's
// other files; a drive that cannot be read is logged and the content rows stand alone
// Payment Files uses only its authorized content list, so a drive's other files cannot expose a check.
if (!isPayment && !content.clientRequest) {
ec.message.pushErrors()
try {
    const folder = ec.service.sync().name('ironstone.commons.DriveServices.get#RecordFolder').parameters({recordEntityName: entityName,
        recordId: recordId, locationList: fileList.map((file) => file.location).filter((location) => location)}).call()
    if (folder.driveId) {
        recordsDriveId = folder.driveId
        recordFolderPath = folder.folderPath
        for (const file of fileList) {
            const path = file.location ? (folder.drivePathByLocation[file.location] ?? null) : null
            file.drivePath = !file.isImmutable && path && folder.folderPath &&
                (path === folder.folderPath || path.startsWith(folder.folderPath + '/')) ? path : null
        }
        if (folder.folderPath) {
            filesUrl = `/qapps/Commons/Files?drive=${encodeURIComponent(folder.driveId)}&path=${encodeURIComponent(folder.folderPath)}`
            const rowPaths = fileList.map((file) => file.drivePath).filter((path) => path)
            const listing = ec.service.sync().name('ironstone.commons.DriveServices.list#FolderView').parameters({driveId: folder.driveId,
                path: folder.folderPath}).requireNewTransaction(true).call()
            if (!ec.message.hasError()) for (const child of Array.from(listing.fileList || [])) {
                if (rowPaths.includes(child.path)) continue
                if (child.isDirectory && rowPaths.some((path) => path.startsWith(child.path + '/'))) continue
                extraList.push({name: child.name, drivePath: child.path, isDirectory: child.isDirectory === true, size: child.size ?? null,
                    sizeText: sizeText(child.size), byName: child.modifiedByName || null, dateText: whenText(child.modified), icon: child.icon || 'sym_o_draft',
                    url: child.isDirectory ? `/qapps/Commons/Files?drive=${encodeURIComponent(folder.driveId)}&path=${encodeURIComponent(child.path)}` : null})
            }
        }
    }
} catch (err) {
    ec.logger.warn(`Record files of ${entityName} ${recordId}: the records drive was not read: ${err && err.message ? err.message : err}`)
} finally {
    if (ec.message.hasError()) ec.logger.warn(`Record files of ${entityName} ${recordId}: the records drive: ${ec.message.getErrorsString()}`)
    ec.message.clearErrors()
    ec.message.popErrors()
}
}
for (const file of fileList) delete file.location

contentType = typeOut.contentType
const recordName = `${recordOut.typeLabel || recordOut.info.recordTypeName} ${recordOut.title || recordId}`
if (!contentType) { ec.message.addError(ec.resource.expand('${recordName} has no files', '', {recordName: recordName})); return }
let key = null
try { key = JSON.parse(String(contentKey)) } catch (err) { key = null }
const fields = contentType.pkFields
if (key == null || typeof key !== 'object' || fields.some((field) => key[field] == null || key[field] === '')) {
    ec.message.addError(ec.l10n.localize('Not a file of this record')); return }
let find = ec.entity.find(contentType.entityName)
for (const field of fields) find = find.condition(field, /Date$/.test(field) ? new Date(Number(key[field])) : String(key[field]))
const row = find.one()
if (row == null || String(row[contentType.keyField]) !== String(recordId)) {
    ec.message.addError(ec.l10n.localize('Not a file of this record')); return }
if (contentType.clientRequest && !contentType.clientContentTypeIds.includes(row[contentType.typeField])) {
    ec.message.addError(ec.l10n.localize('File is not available')); return }
contentRow = row.getMap()
if (recordOut.info.recordEntityName === 'mantle.account.payment.Payment') {
    if (contentRow.contentTypeEnumId === 'PctCheckImage' && !contentType.paymentCanReadCheck)
        throw new Error('PERMISSION_DENIED: Treasury authority is required to read an issued check')
    if (contentType.paymentContentLocked) contentType = Object.assign({}, contentType, {catalogCanChange: false})
}
if (contentRow.isImmutable === 'Y') contentType = Object.assign({}, contentType, {catalogCanChange: false})
// a check's evidence (impl-maintenance P7): never removed
if ((contentType.protectedContentIds || []).includes(String(contentRow.workEffortContentId)))
    contentType = Object.assign({}, contentType, {catalogCanChange: false})
contentLocation = row.contentLocation ? String(row.contentLocation) : null
const last = contentLocation ? contentLocation.substring(contentLocation.lastIndexOf('/') + 1) : null
try { fileName = last ? decodeURIComponent(last) : null } catch (err) { fileName = last }
inlineAllowed = !!fileName && /\.(png|jpe?g|gif|webp|pdf)$/i.test(fileName)

createdList = []
failedList = []
const L = (text) => ec.l10n.localize(text)
const content = typeOut.contentType
const recordName = `${recordOut.typeLabel || recordOut.info.recordTypeName} ${recordOut.title || recordId}`
if (!content) {
    ec.message.addError(ec.resource.expand('A ${typeName} has no files: its record type has no content entity', '',
            {typeName: recordOut.typeLabel || recordOut.info.recordTypeName}))
    return
}
if (content.catalogCanChange === false || !ec.artifactExecution.isPermitted(content.entityName, 'AT_ENTITY', 'create')) {
    ec.message.addError(ec.resource.expand('You may not add files to ${recordName}', '', {recordName: recordName})); return }
if (contentTypeEnumId && content.enumTypeId) {
    const known = ec.entity.find('moqui.basic.Enumeration').condition('enumId', contentTypeEnumId).useCache(true).one()
    if (known == null || known.enumTypeId !== content.enumTypeId) {
        ec.message.addError(ec.resource.expand('${typeId} is not a file type of ${recordName}', '', {typeId: contentTypeEnumId, recordName: recordName}))
        return
    }
}
const files = (Array.isArray(contentFile) ? contentFile : [contentFile]).filter((file) => file != null && typeof file === 'object')
if (files.length === 0) { ec.message.addError(L('Choose one or more files to add')); return }

for (const file of files) {
    const fileName = typeof file.getName === 'function' ? file.getName() : (file.name || L('file'))
    ec.message.pushErrors()
    try {
        let out
        if (content.createService) {
            const parameters = {[content.keyField]: recordId, [content.typeField]: contentTypeEnumId || null,
                description: description || null, contentFile: file}
            out = ec.service.sync().name(content.createService).parameters(parameters).call()
        } else {
            // Facility: no create and save pair; the row, then the file at the place the others use, then its location
            out = ec.service.sync().name('create#' + content.entityName).parameters({[content.keyField]: recordId,
                [content.typeField]: contentTypeEnumId || null}).call()
            if (!ec.message.hasError()) {
                const rowId = out[content.idField]
                const root = ec.user.getPreference('mantle.content.large.root') || 'dbresource://mantle/content'
                const location = `${root}/facility/${recordId}/content_${rowId}/${fileName}`
                const stream = file.getInputStream()
                try { ec.resource.getLocationReference(location).putStream(stream) } finally { if (stream && stream.close) stream.close() }
                ec.service.sync().name('update#' + content.entityName).parameters({[content.idField]: rowId, contentLocation: location}).call()
            }
        }
        if (ec.message.hasError()) throw new Error(ec.message.getErrorsString())
        createdList.push({fileName: fileName, contentId: content.idField ? (out?.[content.idField] ?? null) : null})
    } catch (err) {
        ec.message.clearErrors()
        const why = err && err.message ? err.message : String(err)
        ec.logger.error(`Record files of ${recordOut.info.recordEntityName} ${recordId}: ${fileName} was not added: ${why}`)
        failedList.push({fileName: fileName, error: why})
    } finally {
        ec.message.popErrors()
    }
}
if (createdList.length === 0) {
    ec.message.addError(ec.resource.expand('No file was added to ${recordName}: ${why}', '', {recordName: recordName,
            why: failedList.map((failed) => failed.fileName + ': ' + failed.error).join('; ')}))
    return
}
message = createdList.length === 1 ? ec.resource.expand('Added ${fileName} to ${recordName}', '', {fileName: createdList[0].fileName, recordName: recordName})
        : ec.resource.expand('Added ${count} files to ${recordName}', '', {count: createdList.length, recordName: recordName})
if (failedList.length) message += '; ' + ec.resource.expand('not added: ${names}', '', {names: failedList.map((failed) => failed.fileName).join(', ')})

const content = fileOut.contentType
const row = fileOut.contentRow
fileName = fileOut.fileName || ec.l10n.localize('the file')
const entityName = ec.entity.makeValue(recordEntityName).getEntityName()
const mine = !!row.userId && row.userId === ec.user.userId
const instruction = entityName === 'mantle.work.effort.WorkEffort' && row.contentTypeEnumId === 'WectInstruction'
if (instruction || content.catalogCanChange === false || (!mine && !ec.artifactExecution.isPermitted(entityName, 'AT_ENTITY', 'update'))) {
    ec.message.addError(ec.resource.expand('You may not remove ${fileName}', '', {fileName: fileName})); return }
const keys = {}
for (const field of content.pkFields) keys[field] = row[field]
ec.service.sync().name('delete#' + content.entityName).parameters(keys).call()
if (ec.message.hasError()) return
if (fileOut.contentLocation) {
    try {
        const ref = ec.resource.getLocationReference(fileOut.contentLocation)
        if (ref && ref.getExists()) ref.delete()
    } catch (err) {
        ec.logger.warn(`Record files of ${entityName} ${recordId}: the row of ${fileOut.contentLocation} is removed, the file was not deleted: ${err}`)
    }
}
message = ec.resource.expand('Removed ${fileName}', '', {fileName: fileName})

const clean = (text) => String(text == null ? '' : text).split('/').filter((part) => part && part !== '.').join('/')
const L = (text) => ec.l10n.localize(text)
contentRow = null
canChange = false
recordName = `${recordOut.typeLabel || recordOut.info.recordTypeName} ${recordOut.title || recordId}`
const entityName = recordOut.info.recordEntityName
const content = typeOut.contentType
const rows = content ? Array.from(ec.entity.find(content.entityName).condition(content.keyField, recordId).list()) : []
const folder = ec.service.sync().name('ironstone.commons.DriveServices.get#RecordFolder').parameters({recordEntityName: entityName, recordId: recordId,
    locationList: rows.map((row) => row.contentLocation).filter((location) => location)}).call()
const path = clean(drivePath)
if (!folder.driveId || !folder.folderPath || String(drivePath).split('/').includes('..') || !(path === folder.folderPath || path.startsWith(folder.folderPath + '/'))) {
    ec.message.addError(L('Not a file of this record')); return
}
driveId = folder.driveId
rootLocation = folder.rootLocation
folderPath = folder.folderPath
const row = rows.find((item) => String(item.contentLocation || '') === `${folder.rootLocation}/${path}`)
contentRow = row ? row.getMap() : null
const location = `${folder.rootLocation}/${path}`
const protectedIds = content?.protectedContentIds || []
const immutablePath = rows.some((item) => (item.getMap().isImmutable === 'Y' || protectedIds.includes(String(item.workEffortContentId))) &&
    (item.contentLocation === location || String(item.contentLocation || '').startsWith(location + '/')))
canChange = !immutablePath && content?.catalogCanChange !== false && ((!!contentRow && !!contentRow.userId && contentRow.userId === ec.user.userId) || ec.artifactExecution.isPermitted(entityName, 'AT_ENTITY', 'update'))
if (requireChange && !canChange) ec.message.addError(ec.resource.expand('You may not change the files of ${recordName}', '', {recordName: recordName}))

// the upload below is internal (the drive is read only to its members): the path must be one the user reaches
const access = ec.service.sync().name('org.moqui.resource.FileServices.get#DriveAccess').parameters({driveId: pathOut.driveId, path: drivePath}).call()
if (!access?.drive || !(access.level >= 1)) { ec.message.addError(ec.l10n.localize('File not found')); return }
const file = Array.isArray(contentFile) ? contentFile[0] : contentFile
if (!file || typeof file !== 'object') { ec.message.addError(ec.l10n.localize('Choose the file of the new version')); return }
const slash = drivePath.lastIndexOf('/')
const name = drivePath.slice(slash + 1)
const out = ec.service.sync().name('org.moqui.resource.FileServices.upload#Resource').parameters({driveId: pathOut.driveId,
    path: drivePath.slice(0, slash), fileList: [file], relativePathList: [name], conflictPolicy: 'replace', versionNote: versionNote || null,
    asInternal: true}).disableAuthz().call()
if (ec.message.hasError()) return
const row = Array.from(out.uploadedList || [])[0]
if (!row || row.outcome === 'failed') { ec.message.addError(ec.resource.expand('${name} was not saved: ${why}', '', {name: name, why: row ? row.error : '?'})); return }
versionName = out.versionName ?? null
message = ec.resource.expand('A new version of ${name}', '', {name: name})

const slash = drivePath.lastIndexOf('/')
const name = drivePath.slice(slash + 1)
const short = String(versionName).length === 40 ? String(versionName).slice(0, 10) : String(versionName)
// the version's bytes by its name (location#version reads the current bytes through a reference)
const location = String(infoOut.resource.location)
const bytes = ec.resource.getVersionBytes(location.slice(0, location.indexOf('#') > 0 ? location.indexOf('#') : location.length), versionName)
if (bytes == null) { ec.message.addError(ec.l10n.localize('That version is not there')); return }
const out = ec.service.sync().name('org.moqui.resource.FileServices.upload#Resource').parameters({driveId: pathOut.driveId,
    path: drivePath.slice(0, slash), fileList: [bytes], relativePathList: [name], conflictPolicy: 'replace',
    versionNote: ec.resource.expand('Restored version ${version}', '', {version: short}), asInternal: true}).disableAuthz().call()
if (ec.message.hasError()) return
const row = Array.from(out.uploadedList || [])[0]
if (!row || row.outcome === 'failed') { ec.message.addError(ec.resource.expand('${name} was not restored: ${why}', '', {name: name, why: row ? row.error : '?'})); return }
message = ec.resource.expand('Version ${version} of ${name} restored', '', {version: short, name: name})

createdList = []
failedList = []
const L = (text) => ec.l10n.localize(text)
const content = typeOut.contentType
const entityName = recordOut.info.recordEntityName
const recordName = `${recordOut.typeLabel || recordOut.info.recordTypeName} ${recordOut.title || recordId}`
if (!content || !content.idField) { ec.message.addError(ec.resource.expand('${recordName} takes no files from Files', '', {recordName: recordName})); return }
if (content.catalogCanChange === false || !ec.artifactExecution.isPermitted(content.entityName, 'AT_ENTITY', 'create')) {
    ec.message.addError(ec.resource.expand('You may not add files to ${recordName}', '', {recordName: recordName})); return }
const rows = Array.from(ec.entity.find(content.entityName).condition(content.keyField, recordId).list())
const folder = ec.service.sync().name('ironstone.commons.DriveServices.get#RecordFolder').parameters({recordEntityName: entityName, recordId: recordId,
    locationList: rows.map((row) => row.contentLocation).filter((location) => location)}).call()
const root = folder.rootLocation || String(ec.user.getPreference('mantle.content.root') || 'dbresource://mantle/content').replace(/\/+$/, '')
if (!folder.folderPath) { ec.message.addError(ec.resource.expand('${recordName} has no folder for files yet: upload a file first', '', {recordName: recordName})); return }
const safe = (name) => String(name || 'file').replace(/[\/\\?#%:*"<>|]/g, '_').slice(0, 160)
// each file the user may open, read in a transaction of its own (a file that is refused does not stop the others)
const readable = (item) => {
    ec.message.pushErrors()
    try {
        const out = ec.service.sync().name('org.moqui.resource.FileServices.get#ResourceInfo').parameters({driveId: item.driveId, path: item.path, opened: true})
                .requireNewTransaction(true).call()
        return ec.message.hasError() ? {why: ec.message.getErrorsString()} : {resource: out.resource}
    } finally { ec.message.clearErrors(); ec.message.popErrors() }
}
for (const item of Array.from(itemList || [])) {
    const label = item && item.path ? String(item.path).split('/').pop() : '?'
    ec.message.pushErrors()
    try {
        if (!item || !item.driveId || !item.path) throw new Error(L('No file chosen'))
        const found = readable(item)
        if (!found.resource) throw new Error(found.why || L('File not found'))
        const info = {resource: found.resource}
        if (info.resource.isDirectory) throw new Error(L('A folder is not added; choose its files'))
        const created = ec.service.sync().name('create#' + content.entityName).parameters({[content.keyField]: recordId,
            [content.typeField]: contentTypeEnumId || null, description: description || null, contentDate: ec.user.nowTimestamp,
            userId: ec.user.userId}).call()
        if (ec.message.hasError()) throw new Error(ec.message.getErrorsString())
        const rowId = created[content.idField]
        const name = safe(info.resource.name)
        const target = `${root}/${folder.folderPath}/content_${rowId}/${name}`
        const stream = ec.resource.getLocationReference(info.resource.location).openStream()
        try { ec.resource.getLocationReference(target).putStream(stream) } finally { if (stream && stream.close) stream.close() }
        ec.service.sync().name('update#' + content.entityName).parameters({[content.idField]: rowId, contentLocation: target}).call()
        if (ec.message.hasError()) throw new Error(ec.message.getErrorsString())
        createdList.push({fileName: info.resource.name, contentId: rowId})
    } catch (err) {
        const why = err && err.message ? err.message : String(err)
        ec.logger.warn(`Record files of ${entityName} ${recordId}: ${label} from Files was not added: ${why}`)
        failedList.push({fileName: label, error: why})
    } finally {
        ec.message.clearErrors()
        ec.message.popErrors()
    }
}
if (!createdList.length) {
    ec.message.addError(ec.resource.expand('No file was added to ${recordName}: ${why}', '', {recordName: recordName,
        why: failedList.map((failed) => failed.fileName + ': ' + failed.error).join('; ')}))
    return
}
message = createdList.length === 1 ? ec.resource.expand('Added ${fileName} to ${recordName}', '', {fileName: createdList[0].fileName, recordName: recordName})
        : ec.resource.expand('Added ${count} files to ${recordName}', '', {count: createdList.length, recordName: recordName})
